<?php $query = sd_homepage_posts(); if ( ! $query->have_posts() ) { wp_reset_postdata(); return; } ?><section class="sd-home-section sd-home-articles"><div class="sd-container"><?php sd_homepage_heading( __( 'From the journal', 'social-discovery' ), sd_homepage_get( 'sd_home_articles_title' ) ); ?><div class="<?php echo esc_attr( sd_homepage_grid_class( sd_homepage_get( 'sd_home_articles_columns' ) ) ); ?>"><?php while ( $query->have_posts() ) : $query->the_post(); ?><article class="sd-home-card sd-home-article-card"><?php if ( has_post_thumbnail() ) : ?><a href="<?php the_permalink(); ?>" class="sd-home-article-image"><?php the_post_thumbnail( 'sd-card', array( 'loading' => 'lazy' ) ); ?></a><?php endif; ?><div class="sd-home-card-body"><?php if ( sd_homepage_get( 'sd_home_articles_category' ) ) : ?><div class="sd-breadcrumbs"><?php the_category( ', ' ); ?></div><?php endif; ?><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 24 ) ); ?></p><?php if ( sd_homepage_get( 'sd_home_articles_date' ) ) : ?><time datetime="<?php echo esc_attr( get_the_date( 'c' ) ); ?>"><?php echo esc_html( get_the_date() ); ?></time><?php endif; ?><a class="sd-text-link" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Read more', 'social-discovery' ); ?> <span aria-hidden="true">→</span></a></div></article><?php endwhile; ?></div><?php wp_reset_postdata(); ?></div></section>
